const tabId = 248688717;
// Let's check the DOM structure for location results
const result = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.location-item, .views-row, [class*="location"], [class*="facility"]'));
  // Also check all links or headings with Richmond
  const richmondLinks = Array.from(document.querySelectorAll('a, button, h2, h3, h4'))
    .filter(el => el.textContent && el.textContent.includes('Richmond'))
    .map(el => ({
      tag: el.tagName,
      text: el.textContent.trim().replace(/\s+/g, ' '),
      href: el.href || null,
      className: el.className
    }));
  return {
    cardsCount: cards.length,
    richmondLinks: richmondLinks.slice(0, 20)
  };
});
console.log(JSON.stringify(result, null, 2));

